ga6Y(){return"\u0421\u0435\u043c\u044c\u044f: \u0433\u043e\u0440\u043e\u0434, \u044f\u0437\u044b\u043a\u0438, \u0434\u0430\u0442\u044b \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043d\u0430 \u043d\u0430\u0439\u043c (\u0431\u0435\u0437 \u0444\u0430\u0439\u043b\u0430), \u0434\u0430\u0442\u044b \u0437\u0430\u043c\u0435\u043d\u044b, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u043f\u043e\u0434\u043e\u043f\u0435\u0447\u043d\u044b\u0445 \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0432 \u0434\u043e\u043c\u0435, \u043d\u0443\u0436\u043d\u044b\u0435 \u0434\u043b\u044f \u043f\u043e\u0434\u0431\u043e\u0440\u0430"},
